package bo.com.ganadero.seguridad.application;
import bo.com.ganadero.seguridad.domain.*;import bo.com.ganadero.shared.security.*;import org.springframework.context.ApplicationEventPublisher;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.Instant;import java.util.*;
@Service public class ActualizarPermisosRolUseCase{private final RolRepository repository;private final UserContext context;private final ApplicationEventPublisher events;public ActualizarPermisosRolUseCase(RolRepository repository,UserContext context,ApplicationEventPublisher events){this.repository=repository;this.context=context;this.events=events;}
 @Transactional public Rol execute(UUID id,Set<UUID> permissions,long version){CurrentUser actor=context.requirePermission("ROL_ASIGNAR_PERMISOS");Rol role=repository.replacePermissions(id,actor.empresaId(),permissions,version,actor.userId());events.publishEvent(new SeguridadAuditEvent(actor.empresaId(),actor.userId(),"ASIGNAR_PERMISOS","ROL",id,Instant.now()));return role;}}
